/**
 * Compares `base` against `side` and returns the list of changes: runs of
 * base lines (given as a half-open `[baseStart, baseEnd)` range) replaced by
 * a run of `side` lines. An insertion has `baseStart === baseEnd`; a deletion
 * has an empty `lines` array.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length
  const width = m + 1
  const dp = new Int32Array((n + 1) * width)
  const at = (i, j) => i * width + j

  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[at(i, j)] = dp[at(i + 1, j + 1)] + 1
      } else {
        const dropBase = dp[at(i + 1, j)]
        const dropSide = dp[at(i, j + 1)]
        dp[at(i, j)] = dropBase > dropSide ? dropBase : dropSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[at(i + 1, j)] >= dp[at(i, j + 1)]) {
      // Advancing the base keeps at least as long a remaining subsequence
      // reachable, and ties prefer advancing the base.
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevI, baseEnd: mi, lines: side.slice(prevJ, mj) })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, lines: side.slice(prevJ, m) })
  }
  return changes
}
"}

