/**
 * Groups the changes from both sides against `base` into merge regions: a
 * base line belongs to a "stable" region (untouched by either side) or a
 * region formed by one or more overlapping changes, resolved below.
 *
 * Each resolved region is `{ type: 'stable' | 'mine' | 'theirs' | 'both',
 * lines }` or `{ type: 'conflict', mine, base, theirs }` (arrays of lines).
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(change => ({ ...change, side: 'theirs' }))

  const all = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  let index = 0
  while (index < all.length) {
    let start = all[index].baseStart
    let end = all[index].baseEnd
    const changes = [all[index]]
    index++
    while (index < all.length && all[index].baseStart <= end) {
      if (all[index].baseEnd > end) end = all[index].baseEnd
      changes.push(all[index])
      index++
    }
    groups.push({ baseStart: start, baseEnd: end, changes })
  }

  const regions = []
  let cursor = 0
  for (const group of groups) {
    if (group.baseStart > cursor) {
      regions.push({ type: 'stable', lines: base.slice(cursor, group.baseStart) })
    }
    regions.push(resolveGroup(base, group))
    cursor = group.baseEnd
  }
  if (cursor < base.length) {
    regions.push({ type: 'stable', lines: base.slice(cursor, base.length) })
  }
  return regions
}

function resolveGroup(base, group) {
  const mineChanges = group.changes.filter(change => change.side === 'mine')
  const theirsChanges = group.changes.filter(change => change.side === 'theirs')
  const mineLines = sideLines(base, mineChanges, group.baseStart, group.baseEnd)
  const theirsLines = sideLines(base, theirsChanges, group.baseStart, group.baseEnd)
  const baseLines = base.slice(group.baseStart, group.baseEnd)

  if (linesEqual(mineLines, theirsLines)) return { type: 'both', lines: mineLines }
  if (linesEqual(mineLines, baseLines)) return { type: 'theirs', lines: theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { type: 'mine', lines: mineLines }
  return { type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * Builds one side's replacement for a region: its own changes in place, with
 * any base lines the region covers but that side's changes don't (because
 * the region only exists due to the other side's changes there) kept as-is.
 */
function sideLines(base, changes, start, end) {
  const parts = []
  let cursor = start
  for (const change of changes) {
    if (change.baseStart > cursor) parts.push(base.slice(cursor, change.baseStart))
    parts.push(change.lines)
    cursor = change.baseEnd
  }
  if (cursor < end) parts.push(base.slice(cursor, end))
  return parts.flat()
}

